export interface LocalAiCapabilities {
  secureContext: boolean
  webGpu: boolean
  webAssembly: boolean
  wasmThreads: boolean
  audioEncoder: boolean
  aacEncoder: boolean
}

export type SeparatorBackend = 'webgpu' | 'wasm-single' | 'unsupported'

interface AudioEncoderSupport {
  supported?: boolean
}

interface AudioEncoderConstructorLike {
  isConfigSupported(config: {
    codec: string
    sampleRate: number
    numberOfChannels: number
    bitrate: number
  }): Promise<AudioEncoderSupport>
}

interface GpuDeviceLike {
  destroy?(): void
}

interface GpuAdapterLike {
  requestDevice(): Promise<GpuDeviceLike>
}

interface GpuLike {
  requestAdapter(options?: { powerPreference?: 'low-power' | 'high-performance' }): Promise<GpuAdapterLike | null>
}

export function chooseSeparatorBackend(
  capabilities: Pick<LocalAiCapabilities, 'webGpu' | 'webAssembly'>,
): SeparatorBackend {
  // Mobile Safari can report WebGPU as available but terminate the page while
  // compiling a separation graph. Prefer the single-thread WASM runtime for
  // the low-memory compatibility path; WebGPU remains diagnostic information.
  if (capabilities.webAssembly) return 'wasm-single'
  if (capabilities.webGpu) return 'webgpu'
  return 'unsupported'
}

export async function detectLocalAiCapabilities(): Promise<LocalAiCapabilities> {
  const browserNavigator = navigator as Navigator & { gpu?: GpuLike }
  const browserGlobal = globalThis as typeof globalThis & {
    AudioEncoder?: AudioEncoderConstructorLike
  }
  const encoder = browserGlobal.AudioEncoder
  let aacEncoder = false
  let webGpu = false
  if (browserNavigator.gpu) {
    try {
      const adapter = await browserNavigator.gpu.requestAdapter({ powerPreference: 'high-performance' })
      const device = await adapter?.requestDevice()
      webGpu = Boolean(device)
      device?.destroy?.()
    } catch {
      webGpu = false
    }
  }
  if (encoder) {
    try {
      const support = await encoder.isConfigSupported({
        codec: 'mp4a.40.2',
        sampleRate: 44_100,
        numberOfChannels: 2,
        bitrate: 128_000,
      })
      aacEncoder = support.supported === true
    } catch {
      aacEncoder = false
    }
  }

  return {
    secureContext: globalThis.isSecureContext,
    webGpu,
    webAssembly: typeof WebAssembly !== 'undefined',
    wasmThreads: globalThis.crossOriginIsolated && typeof SharedArrayBuffer !== 'undefined',
    audioEncoder: Boolean(encoder),
    aacEncoder,
  }
}
