import { stemIds, type StemId } from './separation'

export interface StemMixerSettings {
  muted: Record<StemId, boolean>
  solo: Record<StemId, boolean>
  volume: Record<StemId, number>
}

export function createStemMixerSettings(): StemMixerSettings {
  return {
    muted: { bass: false, drums: false, vocals: false, other: false },
    solo: { bass: false, drums: false, vocals: false, other: false },
    volume: { bass: 1, drums: 1, vocals: 1, other: 1 },
  }
}

export function stemGain(id: StemId, settings: StemMixerSettings): number {
  if (settings.muted[id]) return 0
  if (stemIds.some((candidate) => settings.solo[candidate]) && !settings.solo[id]) return 0
  return Math.max(0, Math.min(1, settings.volume[id]))
}
