export function clampEqGain(value: number): number {
  return Math.min(12, Math.max(-12, Number.isFinite(value) ? value : 0))
}

export function clampHighCut(value: number): number {
  return Math.min(20_000, Math.max(500, Number.isFinite(value) ? value : 8_000))
}

export function normalizeEq(value: unknown): EqSettings {
  const flat = createFlatEq()
  if (!value || typeof value !== 'object') return flat
  const candidate = value as Partial<EqSettings>
  const candidateBands = candidate.bands && typeof candidate.bands === 'object'
    ? candidate.bands as Partial<Record<EqBandId, number>>
    : {}
  return {
    bands: Object.fromEntries(eqBands.map((band) => {
      const restored = candidateBands[band.id]
      return [band.id, clampEqGain(typeof restored === 'number' ? restored : 0)]
    })) as Record<EqBandId, number>,
    bypassed: candidate.bypassed === true,
    highCut: {
      enabled: candidate.highCut?.enabled === true,
      frequency: clampHighCut(candidate.highCut?.frequency ?? 8_000),
    },
  }
}
