import { useEffect, useRef, useState } from 'react'
import { formatTime } from '../lib/audio'
import { startPreparedStemSources } from '../lib/audio-unlock'
import { stemIds, type StemId } from '../lib/separation'
import { createStemMixerSettings, stemGain, type StemMixerSettings } from '../lib/stem-mixer'

const labels: Record<StemId, string> = {
  bass: 'Bass',
  drums: 'Drums',
  vocals: 'Vocals',
  other: 'Other',
}

interface MixerGraph {
  context: AudioContext
  buffers: Record<StemId, AudioBuffer>
  master: GainNode
  gains: Record<StemId, GainNode>
  sources: AudioBufferSourceNode[]
  startedAt: number
  offset: number
}

interface Props {
  stems: Record<StemId, Blob>
  duration: number
  onBeforePlay(): void
  registerPause(pause: (() => void) | null): void
  onError(message: string): void
  contextHolder?: { current: AudioContext | null }
  settingsHolder?: { current: StemMixerSettings }
  autoPlay?: boolean
  onEnded?(): void
}

export function StemMixer({ stems, duration, onBeforePlay, registerPause, onError, contextHolder, settingsHolder, autoPlay = false, onEnded }: Props) {
  const bassBlob = stems.bass
  const drumsBlob = stems.drums
  const vocalsBlob = stems.vocals
  const otherBlob = stems.other
  const [settings, setSettings] = useState(() => settingsHolder?.current ?? createStemMixerSettings())
  const [position, setPosition] = useState(0)
  const [playing, setPlaying] = useState(false)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const graphRef = useRef<MixerGraph | null>(null)
  const playingRef = useRef(false)
  const loadingRef = useRef(true)
  const positionRef = useRef(0)
  const settingsRef = useRef(settings)
  settingsRef.current = settings
  if (settingsHolder) settingsHolder.current = settings
  const timerRef = useRef<number | null>(null)
  const disposedRef = useRef(false)
  const pauseRef = useRef<() => void>(() => {})
  const playRef = useRef<() => void>(() => {})
  const autoPlayRef = useRef(autoPlay)
  autoPlayRef.current = autoPlay
  const endedRef = useRef(onEnded)
  endedRef.current = onEnded

  const stopSources = () => {
    const graph = graphRef.current
    if (!graph) return
    for (const source of graph.sources) {
      try { source.stop() } catch { /* A source can already have ended. */ }
      source.disconnect()
    }
    graph.sources = []
  }

  const currentPosition = () => {
    const graph = graphRef.current
    if (!graph || !playingRef.current) return positionRef.current
    return Math.min(duration, graph.offset + Math.max(0, graph.context.currentTime - graph.startedAt))
  }

  const pause = () => {
    if (!playingRef.current) return
    const nextPosition = currentPosition()
    playingRef.current = false
    if (timerRef.current !== null) window.clearInterval(timerRef.current)
    timerRef.current = null
    stopSources()
    positionRef.current = nextPosition
    setPosition(nextPosition)
    setPlaying(false)
  }
  pauseRef.current = pause

  useEffect(() => {
    registerPause(() => pauseRef.current())
    return () => registerPause(null)
  }, [registerPause])

  useEffect(() => {
    disposedRef.current = false
    let active = true
    loadingRef.current = true
    const shared = contextHolder?.current
    const context = shared && shared.state !== 'closed' ? shared : new AudioContext()
    const ownsContext = !contextHolder
    if (contextHolder) contextHolder.current = context
    const prepareGraph = async () => {
      try {
        const blobs: Record<StemId, Blob> = { bass: bassBlob, drums: drumsBlob, vocals: vocalsBlob, other: otherBlob }
        const buffers = {} as Record<StemId, AudioBuffer>
        for (const id of stemIds) {
          buffers[id] = await context.decodeAudioData(await blobs[id].arrayBuffer())
          if (!active) return
        }
        const master = context.createGain()
        master.gain.value = 0.8
        master.connect(context.destination)
        const gains = {} as Record<StemId, GainNode>
        for (const id of stemIds) {
          const gain = context.createGain()
          gain.gain.value = stemGain(id, settingsRef.current)
          gain.connect(master)
          gains[id] = gain
        }
        graphRef.current = { context, buffers, master, gains, sources: [], startedAt: 0, offset: 0 }
        if (active) {
          loadingRef.current = false
          setLoading(false)
          if (autoPlayRef.current) {
            if (context.state === 'running') playRef.current()
            else {
              const message = 'iPhone 暫停了音訊，請按「播放四軌」繼續。'
              setError(message)
              onError(message)
            }
          }
        }
      } catch (reason) {
        if (!active) return
        loadingRef.current = false
        setLoading(false)
        const message = reason instanceof Error ? reason.message : '四軌播放器無法解碼音訊。'
        setError(message)
        onError(message)
      }
    }
    void prepareGraph()
    return () => {
      active = false
      disposedRef.current = true
      if (timerRef.current !== null) window.clearInterval(timerRef.current)
      stopSources()
      const graph = graphRef.current
      if (graph) {
        for (const id of stemIds) graph.gains[id].disconnect()
        graph.master.disconnect()
      }
      if (ownsContext && context.state !== 'closed') void context.close()
      graphRef.current = null
    }
  }, [bassBlob, contextHolder, drumsBlob, onError, otherBlob, vocalsBlob])

  useEffect(() => {
    const graph = graphRef.current
    if (!graph) return
    for (const id of stemIds) {
      graph.gains[id].gain.setTargetAtTime(stemGain(id, settings), graph.context.currentTime, 0.015)
    }
  }, [settings, loading])

  const play = () => {
    if (loadingRef.current || playingRef.current) return
    setError(null)
    try {
      onBeforePlay()
      const graph = graphRef.current
      if (disposedRef.current || !graph) throw new Error('四軌尚未載入完成，請稍後再試。')
      const offset = positionRef.current >= duration - 0.02 ? 0 : positionRef.current
      const startedAt = graph.context.currentTime + 0.04
      const { sources, activation } = startPreparedStemSources(graph.context, graph.buffers, graph.gains, startedAt, offset)
      graph.sources = sources
      void activation.catch((reason: unknown) => {
        pauseRef.current()
        const message = reason instanceof Error ? reason.message : 'iPhone 無法啟動四軌音訊。'
        setError(message)
        onError(message)
      })
      graph.startedAt = startedAt
      graph.offset = offset
      positionRef.current = offset
      setPosition(offset)
      playingRef.current = true
      setPlaying(true)
      timerRef.current = window.setInterval(() => {
        const nextPosition = currentPosition()
        if (nextPosition >= duration - 0.01) {
          pauseRef.current()
          positionRef.current = duration
          setPosition(duration)
          endedRef.current?.()
        } else {
          setPosition(nextPosition)
        }
      }, 100)
    } catch (reason) {
      stopSources()
      const message = reason instanceof Error ? reason.message : '四軌播放器無法載入音訊。'
      setError(message)
      onError(message)
    }
  }
  playRef.current = play

  const seek = (nextPosition: number) => {
    const wasPlaying = playingRef.current
    if (wasPlaying) pause()
    const next = Math.max(0, Math.min(duration, nextPosition))
    positionRef.current = next
    setPosition(next)
    if (wasPlaying) play()
  }

  const toggleMute = (id: StemId) => {
    setSettings((previous) => ({
      ...previous,
      muted: { ...previous.muted, [id]: !previous.muted[id] },
    }))
  }
  const toggleSolo = (id: StemId) => {
    setSettings((previous) => ({
      ...previous,
      solo: { ...previous.solo, [id]: !previous.solo[id] },
    }))
  }

  return (
    <section className="stem-mixer" aria-label="四軌同步播放器">
      <div className="stem-transport">
        <button type="button" disabled={loading || !graphRef.current} onClick={() => playing ? pause() : play()}>
          {loading ? '載入四軌…' : playing ? '暫停' : '播放四軌'}
        </button>
        <span>{formatTime(position, true)} / {formatTime(duration, true)}</span>
      </div>
      <input
        className="stem-seek"
        type="range"
        min="0"
        max={duration}
        step="0.01"
        value={position}
        aria-label="四軌播放位置"
        onChange={(event) => seek(Number(event.target.value))}
      />
      <div className="stem-tracks">
        {stemIds.map((id) => (
          <div className="stem-track" key={id}>
            <div className="stem-track-main">
              <strong>{labels[id]}</strong>
              <div className="stem-track-actions">
                <button type="button" className={settings.muted[id] ? 'active' : ''} aria-pressed={settings.muted[id]} onClick={() => toggleMute(id)}>{settings.muted[id] ? '已靜音' : '靜音'}</button>
                <button type="button" className={settings.solo[id] ? 'active' : ''} aria-pressed={settings.solo[id]} onClick={() => toggleSolo(id)}>Solo</button>
              </div>
            </div>
            <label>
              <span>音量 {Math.round(settings.volume[id] * 100)}%</span>
              <input
                type="range"
                min="0"
                max="1"
                step="0.01"
                value={settings.volume[id]}
                aria-label={`${labels[id]} 音量`}
                onChange={(event) => setSettings((previous) => ({
                  ...previous,
                  volume: { ...previous.volume, [id]: Number(event.target.value) },
                }))}
              />
            </label>
          </div>
        ))}
      </div>
      {error && <p className="stem-mixer-error" role="alert">{error}</p>}
      <small>四軌共用同一時間軸；Solo 只聽選定音軌。</small>
    </section>
  )
}
