import { useEffect, useRef, useState } from 'react'
import type { LocalAiCapabilities } from '../lib/ai-capabilities'
import { chooseSeparatorBackend } from '../lib/ai-capabilities'
import {
  deleteCachedModel,
  deleteFullSongSegments,
  deleteStoredStemSet,
  getCachedModel,
  getFullSongSegment,
  getStoredStemSet,
  listFullSongSegments,
  saveCachedModel,
  saveFullSongSegment,
  saveStoredStemSet,
  type CachedAiModel,
  type FullSongSegmentMeta,
  type StoredStemSet,
} from '../lib/ai-storage'
import { formatBytes, formatTime } from '../lib/audio'
import {
  approximateModelBytes,
  approximateRuntimeBytes,
  cacheAiRuntime,
  deleteCachedAiAssets,
  downloadSeparatorModel,
  getCachedSeparatorModel,
  hasCachedSeparatorModel,
  separationSampleRate,
  stemIds,
} from '../lib/separation'
import {
  appendCompactSeparationSegment,
  createCompactSeparationAccumulator,
  finishCompactSeparation,
} from '../lib/compact-separation'
import { separateClipsInWorker } from '../lib/separation-worker-client'
import { getStorageEstimate } from '../lib/storage'
import { encodeStereoPcm16Wav } from '../lib/wav'
import { encodeStereoM4a } from '../lib/m4a'
import { nextFullSongWindow, type FullSongWindow } from '../lib/full-song-plan'
import { createCapturePlan, sliceCapturedClip, type CapturedAudio } from '../lib/capture-plan'
import { StemMixer } from './StemMixer'
import { createStemMixerSettings } from '../lib/stem-mixer'

type JobPhase = 'idle' | 'downloading' | 'decoding' | 'loading-model' | 'separating' | 'encoding' | 'ready'
type RecordedJobPhase = Exclude<JobPhase, 'idle' | 'ready'>

const interruptedJobKey = 'transcribe-pwa-interrupted-ai-job-v1'

const phaseLabels: Record<RecordedJobPhase, string> = {
  downloading: '下載 AI 元件',
  decoding: '擷取音訊',
  'loading-model': '載入 AI 模型',
  separating: '執行分離',
  encoding: '壓縮四軌',
}

function recordJobPhase(phase: RecordedJobPhase): void {
  localStorage.setItem(interruptedJobKey, JSON.stringify({ phase, recordedAt: new Date().toISOString() }))
}

function clearRecordedJob(): void {
  localStorage.removeItem(interruptedJobKey)
}

function readInterruptedJob(): string | null {
  try {
    const value = JSON.parse(localStorage.getItem(interruptedJobKey) ?? '') as {
      phase?: RecordedJobPhase
      recordedAt?: string
    }
    clearRecordedJob()
    if (!value.phase || !(value.phase in phaseLabels)) return null
    return `上一次在「${phaseLabels[value.phase]}」時被中止。若畫面曾閃白或重新載入，通常是 iPhone 關閉了使用過多記憶體的頁面。`
  } catch {
    clearRecordedJob()
    return null
  }
}

interface StemResult {
  sourceImportedAt: string
  sourceName: string
  startTime: number
  duration: number
  format: 'wav' | 'm4a'
  bass: Blob
  drums: Blob
  vocals: Blob
  other: Blob
  saved: boolean
}

interface Props {
  capabilities: LocalAiCapabilities | null
  checkingCapabilities: boolean
  currentTime: number
  sourceDuration: number
  sourceImportedAt: string
  sourceName: string
  onCheckCapabilities(): Promise<void>
  onBeforeSeparation(): void
  onBeforeStemPlayback(): void
  registerStemPause(pause: (() => void) | null): void
  captureClip(startTime: number, duration: number, signal: AbortSignal): Promise<CapturedAudio>
  onError(message: string): void
  onStorageChanged(): Promise<void>
}

function fromStored(stored: Omit<StoredStemSet, 'key' | 'savedAt'>): StemResult {
  return {
    sourceImportedAt: stored.sourceImportedAt,
    sourceName: stored.sourceName,
    startTime: stored.startTime,
    duration: stored.duration,
    format: stored.format ?? 'wav',
    bass: stored.bass,
    drums: stored.drums,
    vocals: stored.vocals,
    other: stored.other,
    saved: true,
  }
}

export function AiSeparationPanel({
  capabilities,
  checkingCapabilities,
  currentTime,
  sourceDuration,
  sourceImportedAt,
  sourceName,
  onCheckCapabilities,
  onBeforeSeparation,
  onBeforeStemPlayback,
  registerStemPause,
  captureClip,
  onError,
  onStorageChanged,
}: Props) {
  const downloadControllerRef = useRef<AbortController | null>(null)
  const jobControllerRef = useRef<AbortController | null>(null)
  const segmentSelectionRef = useRef(0)
  const fullPlaybackContextRef = useRef<AudioContext | null>(null)
  const fullMixerSettingsRef = useRef(createStemMixerSettings())
  const [model, setModel] = useState<CachedAiModel | null>(null)
  const [checkingCache, setCheckingCache] = useState(true)
  const [phase, setPhase] = useState<JobPhase>('idle')
  const [progress, setProgress] = useState(0)
  const [progressText, setProgressText] = useState('')
  const [experimentLength, setExperimentLength] = useState<15 | 30>(15)
  const segmentLength = 8
  const overlapDuration = 0.5
  const [result, setResult] = useState<StemResult | null>(null)
  const [fullSegments, setFullSegments] = useState<FullSongSegmentMeta[]>([])
  const [selectedFullResult, setSelectedFullResult] = useState<StemResult | null>(null)
  const [selectedFullIndex, setSelectedFullIndex] = useState<number | null>(null)
  const [autoPlayFullIndex, setAutoPlayFullIndex] = useState<number | null>(null)
  const [resultMode, setResultMode] = useState<'preview' | 'full'>('preview')
  const [legacyResult, setLegacyResult] = useState(false)
  const [interruptedNotice, setInterruptedNotice] = useState(readInterruptedJob)

  const busy = phase === 'downloading' || phase === 'decoding' || phase === 'loading-model' || phase === 'separating' || phase === 'encoding'
  const separatorBackend = capabilities ? chooseSeparatorBackend(capabilities) : 'unsupported'
  const wasmReady = separatorBackend === 'wasm-single'
  const fullCompletedSeconds = fullSegments.at(-1)
    ? Math.min(sourceDuration, fullSegments.at(-1)!.startTime + fullSegments.at(-1)!.duration)
    : 0
  const fullSongComplete = sourceDuration > 0 && fullCompletedSeconds >= sourceDuration - 0.05

  useEffect(() => {
    let active = true
    segmentSelectionRef.current += 1
    setCheckingCache(true)
    setFullSegments([])
    setSelectedFullResult(null)
    setSelectedFullIndex(null)
    setAutoPlayFullIndex(null)
    fullMixerSettingsRef.current = createStemMixerSettings()
    setResult(null)
    setResultMode('preview')
    void Promise.all([getCachedModel(), hasCachedSeparatorModel(), getStoredStemSet(), listFullSongSegments(sourceImportedAt)])
      .then(([cachedModel, modelFileExists, storedStems, storedSegments]) => {
        if (!active) return
        setModel(modelFileExists ? cachedModel : null)
        setFullSegments(storedSegments)
        if (storedSegments.length > 0) {
          const last = storedSegments.at(-1)
          if (last) {
            const selection = ++segmentSelectionRef.current
            setResultMode('full')
            setSelectedFullIndex(last.index)
            void getFullSongSegment(last.index).then((segment) => {
              if (active && selection === segmentSelectionRef.current && segment?.sourceImportedAt === sourceImportedAt) setSelectedFullResult(fromStored(segment))
            }).catch((reason: unknown) => {
              if (active && selection === segmentSelectionRef.current) onError(reason instanceof Error ? reason.message : '無法讀取整首分離片段。')
            })
          }
        }
        if (cachedModel && !modelFileExists) void deleteCachedModel()
        if (storedStems?.sourceImportedAt === sourceImportedAt && storedStems.vocals instanceof Blob && storedStems.other instanceof Blob) {
          setResult(fromStored(storedStems))
          setLegacyResult(false)
          setPhase('ready')
        } else if (storedStems?.sourceImportedAt === sourceImportedAt) {
          setLegacyResult(true)
          setProgressText('找到舊版兩軌結果；請重新分離，就能取得四軌。')
        }
      })
      .catch((reason: unknown) => {
        if (active) onError(reason instanceof Error ? reason.message : '無法讀取本機 AI 資料。')
      })
      .finally(() => {
        if (active) setCheckingCache(false)
      })
    return () => {
      active = false
      downloadControllerRef.current?.abort()
      jobControllerRef.current?.abort()
      const playbackContext = fullPlaybackContextRef.current
      if (playbackContext && playbackContext.state !== 'closed') void playbackContext.close()
      fullPlaybackContextRef.current = null
    }
  }, [onError, sourceImportedAt])

  const downloadModel = async () => {
    if (!window.confirm('要下載約 35 MB 的低記憶體 AI 元件嗎？下載一次後會保存在這支手機，可供離線使用。')) return
    const estimate = await getStorageEstimate()
    if (estimate?.quota !== undefined && estimate.usage !== undefined) {
      const available = estimate.quota - estimate.usage
      if (available < approximateModelBytes + approximateRuntimeBytes + 64 * 1024 * 1024) {
        onError('手機提供給這個網站的可用空間不足。請先釋放至少 120 MB，再下載 AI 元件。')
        return
      }
    }

    const controller = new AbortController()
    downloadControllerRef.current = controller
    recordJobPhase('downloading')
    setPhase('downloading')
    setProgress(0)
    setProgressText('正在連線到模型下載來源…')
    try {
      const size = await downloadSeparatorModel(controller.signal, ({ loaded, total }) => {
        setProgress(Math.min(loaded / (total ?? approximateModelBytes), 1))
        setProgressText(`${formatBytes(loaded)} / ${total ? formatBytes(total) : '約 22 MB'}`)
      })
      const cached = await saveCachedModel(size)
      setProgressText('模型已保存；正在下載約 12 MB 的低記憶體 AI 執行引擎…')
      await cacheAiRuntime(controller.signal)
      setModel(cached)
      setPhase('idle')
      setProgress(0)
      setProgressText('模型已保存在這支手機。')
      clearRecordedJob()
      await onStorageChanged()
    } catch (reason) {
      await Promise.allSettled([deleteCachedModel(), deleteCachedAiAssets()])
      setModel(null)
      clearRecordedJob()
      setPhase('idle')
      if (reason instanceof DOMException && reason.name === 'AbortError') {
        setProgressText('下載已取消。')
      } else {
        onError(reason instanceof Error ? reason.message : 'AI 模型下載失敗。')
      }
    } finally {
      downloadControllerRef.current = null
    }
  }

  const removeModel = async () => {
    if (!window.confirm('要從這支手機刪除約 35 MB 的 AI 模型與執行引擎嗎？下次分離時需要重新下載。')) return
    await deleteCachedModel()
    await deleteCachedAiAssets()
    setModel(null)
    setProgressText('AI 模型已從手機刪除。')
    await onStorageChanged()
  }

  const runExperiment = async (mode: 'preview' | 'full' = 'preview') => {
    if (!model || !wasmReady) return
    let fullWindow: FullSongWindow | null = null
    if (mode === 'full') {
      if (!capabilities?.aacEncoder) {
        onError('整首分離需要這支手機支援 AAC／M4A，避免四軌 WAV 佔滿儲存空間。')
        return
      }
      try {
        fullWindow = nextFullSongWindow(fullSegments, sourceDuration, experimentLength)
      } catch (reason) {
        onError(reason instanceof Error ? reason.message : '整首分離進度無法繼續。')
        return
      }
      if (!fullWindow) return
    }
    const startTime = fullWindow?.startTime ?? currentTime
    const captureDuration = fullWindow?.duration ?? Math.min(experimentLength, Math.max(0, sourceDuration - currentTime))
    if (captureDuration <= 0.05) {
      onError('目前位置已經在歌曲結尾，請把播放位置往前移。')
      return
    }
    const controller = new AbortController()
    jobControllerRef.current = controller
    onBeforeSeparation()
    if (mode === 'preview') setResult(null)
    setProgress(0)
    setPhase('loading-model')
    recordJobPhase('loading-model')
    setProgressText(fullWindow ? `正在準備整首歌曲第 ${fullWindow.index + 1} 段…` : '正在準備低記憶體 AI 模型…')
    try {
      const modelBlob = await getCachedSeparatorModel()
      if (!modelBlob) throw new Error('找不到已下載的 AI 模型，請刪除 AI 元件後重新下載。')
      setPhase('decoding')
      recordJobPhase('decoding')
      setProgressText(`正在連續擷取 ${captureDuration.toFixed(1)} 秒；請保持畫面開啟…`)
      const recording = await captureClip(startTime, captureDuration, controller.signal)
      const capturePlan = createCapturePlan(
        0,
        recording.duration,
        recording.duration,
        segmentLength,
        overlapDuration,
      )
      if (capturePlan.length === 0) throw new Error('音訊擷取時間不足，請重試。')
      const outputSamples = Math.round(recording.duration * separationSampleRate)
      const accumulated = createCompactSeparationAccumulator(outputSamples)
      for (let index = 0; index < capturePlan.length; index += 1) {
        const segment = capturePlan[index]
        if (!segment) continue
        if (controller.signal.aborted) throw new DOMException('AI 分離已取消。', 'AbortError')
        const clip = sliceCapturedClip(recording, segment, separationSampleRate)
        setProgress((index + 0.12) / capturePlan.length)
        setPhase('loading-model')
        recordJobPhase('loading-model')
        setProgressText(`正在為第 ${index + 1} / ${capturePlan.length} 段建立獨立 AI 工作區…`)
        {
          const separated = await separateClipsInWorker(modelBlob, [clip], controller.signal, ({
            progress: inferenceProgress,
          }) => {
            setPhase('separating')
            recordJobPhase('separating')
            setProgress((index + Math.max(inferenceProgress, 0.15)) / capturePlan.length)
            setProgressText(`正在背景分離第 ${index + 1} / ${capturePlan.length} 段；可按取消，但請不要切換其他 App…`)
          })
          const separatedSegment = separated[0]
          if (!separatedSegment) throw new Error(`第 ${index + 1} 段沒有產生分離結果。`)
          appendCompactSeparationSegment(
            accumulated,
            separatedSegment,
            Math.round(segment.startTime * separationSampleRate),
            Math.round(overlapDuration * separationSampleRate),
          )
        }
        setProgress((index + 1) / capturePlan.length)
        if (index < capturePlan.length - 1) {
          setPhase('loading-model')
          setProgressText(`第 ${index + 1} 段完成；正在釋放 AI 記憶體…`)
          await new Promise((resolve) => window.setTimeout(resolve, 5_000))
        }
      }
      const outputGain = finishCompactSeparation(accumulated)
      const resultDuration = accumulated.bass.left.length / separationSampleRate
      let encoded: Record<(typeof stemIds)[number], Blob> | null = null
      let outputFormat: 'wav' | 'm4a' = 'wav'
      if (capabilities?.aacEncoder) {
        setPhase('encoding')
        recordJobPhase('encoding')
        setProgress(0)
        try {
          const compressed = {} as Record<(typeof stemIds)[number], Blob>
          for (const [index, id] of stemIds.entries()) {
            setProgressText(`正在本機壓縮 ${id} · ${index + 1} / 4 軌…`)
            compressed[id] = await encodeStereoM4a(
              accumulated[id].left,
              accumulated[id].right,
              outputGain,
              controller.signal,
            )
            setProgress((index + 1) / stemIds.length)
          }
          encoded = compressed
          outputFormat = 'm4a'
        } catch (reason) {
          if (reason instanceof DOMException && reason.name === 'AbortError') throw reason
          setProgressText('這支手機無法完成 M4A 壓縮，改用 WAV 保留結果。')
        }
      }
      if (!encoded) {
        if (mode === 'full') throw new Error('本段 M4A 壓縮未成功；已完成的整首片段仍保留在手機。')
        encoded = {
          bass: encodeStereoPcm16Wav(accumulated.bass.left, accumulated.bass.right, outputGain),
          drums: encodeStereoPcm16Wav(accumulated.drums.left, accumulated.drums.right, outputGain),
          vocals: encodeStereoPcm16Wav(accumulated.vocals.left, accumulated.vocals.right, outputGain),
          other: encodeStereoPcm16Wav(accumulated.other.left, accumulated.other.right, outputGain),
        }
      }
      const nextResult: StemResult = {
        sourceImportedAt,
        sourceName,
        startTime,
        duration: resultDuration,
        format: outputFormat,
        ...encoded,
        saved: false,
      }
      if (fullWindow) {
        if (nextResult.format !== 'm4a') throw new Error('整首分離只能保存 M4A 片段。')
        const saved = await saveFullSongSegment(fullWindow.index, {
          sourceImportedAt,
          sourceName,
          startTime,
          duration: resultDuration,
          sampleRate: 44_100,
          format: 'm4a',
          bass: nextResult.bass,
          drums: nextResult.drums,
          vocals: nextResult.vocals,
          other: nextResult.other,
        })
        setFullSegments((previous) => [...previous, saved])
        segmentSelectionRef.current += 1
        setSelectedFullResult({ ...nextResult, saved: true })
        setSelectedFullIndex(fullWindow.index)
        setAutoPlayFullIndex(null)
        setResultMode('full')
        await onStorageChanged()
      } else {
        setResult(nextResult)
        setResultMode('preview')
      }
      setPhase('ready')
      setProgress(1)
      setProgressText(fullWindow
        ? `第 ${fullWindow.index + 1} 段已存到手機。可按「繼續下一段」；若關閉頁面，下次仍從這裡續做。`
        : `${resultDuration.toFixed(1)} 秒連續分離完成，已製作 ${outputFormat.toUpperCase()} 四軌。結果目前只在記憶體中。`)
      clearRecordedJob()
    } catch (reason) {
      clearRecordedJob()
      setPhase('idle')
      setProgress(0)
      if (reason instanceof DOMException && reason.name === 'AbortError') {
        setProgressText(fullWindow ? '本段已取消；之前完成的整首片段仍保留在手機。' : '處理已取消，未完成的片段已清除。')
        return
      }
      const message = reason instanceof Error ? reason.message : '本機 AI 分離失敗。'
      const memoryHint = /memory|buffer|device lost|allocation|out of/i.test(message)
        ? ' 這支 iPhone 可能無法連續完成目前長度，請重新開啟程式後改用 15 秒，並回報停止階段。'
        : ''
      onError(`${message}${memoryHint}`)
    } finally {
      jobControllerRef.current = null
    }
  }

  const keepResult = async () => {
    if (!result) return
    try {
      await saveStoredStemSet({
        sourceImportedAt: result.sourceImportedAt,
        sourceName: result.sourceName,
        startTime: result.startTime,
        duration: result.duration,
        sampleRate: 44_100,
        format: result.format,
        bass: result.bass,
        drums: result.drums,
        vocals: result.vocals,
        other: result.other,
      })
      setResult({ ...result, saved: true })
      setProgressText('四軌結果已保留在這支手機。')
      await onStorageChanged()
    } catch (reason) {
      onError(reason instanceof Error ? reason.message : '無法保留分離結果。')
    }
  }

  const removeResult = async () => {
    await deleteStoredStemSet()
    setResult(null)
    setPhase('idle')
    setProgress(0)
    setProgressText('分離結果已刪除。')
    await onStorageChanged()
  }

  const removeLegacyResult = async () => {
    if (!window.confirm('要刪除舊版兩軌結果，釋放手機儲存空間嗎？')) return
    await deleteStoredStemSet()
    setLegacyResult(false)
    setProgressText('舊版兩軌結果已刪除。')
    await onStorageChanged()
  }

  const selectFullSegment = async (segment: FullSongSegmentMeta, continuePlayback = false) => {
    if (busy) return
    const selection = ++segmentSelectionRef.current
    setSelectedFullIndex(segment.index)
    setAutoPlayFullIndex(continuePlayback ? segment.index : null)
    setSelectedFullResult(null)
    setResultMode('full')
    try {
      const stored = await getFullSongSegment(segment.index)
      if (!stored || stored.sourceImportedAt !== sourceImportedAt) throw new Error('找不到這段四軌音訊，請重新開啟頁面。')
      if (selection === segmentSelectionRef.current) setSelectedFullResult(fromStored(stored))
    } catch (reason) {
      if (selection === segmentSelectionRef.current) onError(reason instanceof Error ? reason.message : '無法讀取整首分離片段。')
    }
  }

  const removeFullResults = async () => {
    if (!window.confirm('要刪除這首歌已完成的所有四軌片段嗎？刪除後必須從第一段重新分離。')) return
    try {
      await deleteFullSongSegments()
      segmentSelectionRef.current += 1
      setFullSegments([])
      setSelectedFullResult(null)
      setSelectedFullIndex(null)
      setAutoPlayFullIndex(null)
      const playbackContext = fullPlaybackContextRef.current
      if (playbackContext && playbackContext.state !== 'closed') void playbackContext.close()
      fullPlaybackContextRef.current = null
      setResultMode(result ? 'preview' : 'full')
      setProgressText('整首分離片段已從手機刪除。')
      await onStorageChanged()
    } catch (reason) {
      onError(reason instanceof Error ? reason.message : '無法刪除整首分離片段。')
    }
  }

  if (checkingCache) {
    return <section className="panel ai-panel"><p>正在檢查手機內的 AI 模型…</p></section>
  }

  return (
    <section className="panel ai-panel">
      <div className="panel-heading"><span>本機 AI 分離實驗</span><b>音樂不會上傳</b></div>
      {interruptedNotice && (
        <div className="ai-interrupted" role="alert">
          <span>{interruptedNotice}</span>
          <button type="button" onClick={() => setInterruptedNotice(null)}>知道了</button>
        </div>
      )}
      {!capabilities ? (
        <>
          <p>先確認這支 iPhone 能否使用低記憶體 CPU／WASM；這一步不會下載約 35 MB 的手機版 AI 元件。</p>
          <button className="ai-check-button" type="button" disabled={checkingCapabilities} onClick={() => void onCheckCapabilities()}>
            {checkingCapabilities ? '正在檢查…' : '檢查這支手機'}
          </button>
        </>
      ) : (
        <div className="capability-results">
          <span>安全連線<strong>{capabilities.secureContext ? '可用' : '不可用'}</strong></span>
          <span>低記憶體模式<strong>{capabilities.webAssembly ? 'CPU／WASM' : '不支援'}</strong></span>
          <span>WebGPU<strong>{capabilities.webGpu ? '可用但停用' : '不可用'}</strong></span>
          <span>AAC／M4A 壓縮<strong>{capabilities.aacEncoder ? '可用' : '尚不可用'}</strong></span>
        </div>
      )}

      {capabilities && !wasmReady && (
        <p className="ai-warning">這支手機沒有可用的 WebAssembly，不能進行低記憶體本機 AI 分離。</p>
      )}

      {wasmReady && !model && (
        <div className="ai-step">
          <p>手機符合相容模式條件。這版不使用 WebGPU，改用較慢但較穩定的單執行緒 CPU／WASM。</p>
          <button className="ai-check-button" type="button" disabled={busy} onClick={() => void downloadModel()}>下載低記憶體 AI 元件（約 35 MB）</button>
        </div>
      )}

      {model && (
        <div className="ai-step">
          <div className="model-row">
            <span>SCNet Mobile<strong>已安裝 · 模型 {formatBytes(model.size)}</strong></span>
            <button type="button" disabled={busy} onClick={() => void removeModel()}>刪除模型</button>
          </div>
          <p>每次處理一小段並產生四軌。15 秒較穩定；30 秒可減少操作次數，但較容易超出手機記憶體。</p>
          <div className="clip-length-options" role="group" aria-label="每次處理長度">
            <button type="button" className={experimentLength === 15 ? 'active' : ''} aria-pressed={experimentLength === 15} disabled={busy} onClick={() => setExperimentLength(15)}>15 秒 · 較穩定</button>
            <button type="button" className={experimentLength === 30 ? 'active' : ''} aria-pressed={experimentLength === 30} disabled={busy} onClick={() => setExperimentLength(30)}>30 秒 · 更多記憶體</button>
          </div>
          <div className="clip-controls">
            <span>測試長度最多 {experimentLength} 秒</span>
            <span>起點 {formatTime(currentTime, true)}</span>
          </div>
          <button className="ai-check-button" type="button" disabled={busy} onClick={() => void runExperiment()}>
            {busy && phase !== 'downloading' ? 'AI 正在處理…' : `分離目前位置後 ${experimentLength} 秒`}
          </button>
          <div className="full-song-controls">
            <strong>整首歌曲 · 分段續做</strong>
            <p>從歌曲開頭依序分離，每次 {experimentLength} 秒。完成一段就壓成 M4A 留在手機；關閉後可從下一段繼續。已完成片段可依序播放，但轉段仍可能有短暫間隔。</p>
            <span>已完成 {formatTime(fullCompletedSeconds, true)} / {formatTime(sourceDuration, true)} · {fullSegments.length} 段 · {formatBytes(fullSegments.reduce((sum, segment) => sum + segment.size, 0))}</span>
            <progress max={Math.max(sourceDuration, 1)} value={fullCompletedSeconds} aria-label="整首分離進度" />
            <button className="ai-check-button" type="button" disabled={busy || fullSongComplete || sourceDuration <= 0 || !capabilities?.aacEncoder} onClick={() => void runExperiment('full')}>
              {busy && phase !== 'downloading' ? 'AI 正在處理…' : fullSongComplete ? '所有片段已分離' : fullSegments.length ? `繼續下一段 · 第 ${fullSegments.length + 1} 段` : '從開頭開始整首分離'}
            </button>
            {!capabilities?.aacEncoder && <small>此手機尚未提供 AAC／M4A 壓縮，整首分離暫不可用；上方短片段測試仍可使用 WAV。</small>}
          </div>
        </div>
      )}

      {phase === 'downloading' && (
        <button className="ai-cancel-button" type="button" onClick={() => downloadControllerRef.current?.abort()}>取消下載</button>
      )}
      {busy && phase !== 'downloading' && (
        <button className="ai-cancel-button" type="button" onClick={() => jobControllerRef.current?.abort()}>取消處理</button>
      )}

      {(busy || progressText) && (
        <div className="ai-progress" aria-live="polite">
          {(phase === 'downloading' || phase === 'decoding' || phase === 'loading-model' || phase === 'separating' || phase === 'encoding') && <progress max="1" value={progress} />}
          <span>{progressText}</span>
        </div>
      )}

      {legacyResult && !result && <button className="ai-cancel-button" type="button" disabled={busy} onClick={() => void removeLegacyResult()}>刪除舊版兩軌結果</button>}

      {result && fullSegments.length > 0 && (
        <div className="result-switch" role="group" aria-label="分離結果類型">
          <button type="button" className={resultMode === 'preview' ? 'active' : ''} disabled={busy} onClick={() => setResultMode('preview')}>短片段測試</button>
          <button type="button" className={resultMode === 'full' ? 'active' : ''} disabled={busy} onClick={() => setResultMode('full')}>整首進度</button>
        </div>
      )}

      {result && resultMode === 'preview' && (
        <div className="stem-results">
          <div className="stem-result-heading">
            <strong>分離結果</strong>
            <span>{formatTime(result.startTime, true)} 起 · {result.duration.toFixed(1)} 秒 · {result.format.toUpperCase()}</span>
          </div>
          <StemMixer
            key={`preview-${result.startTime}-${result.duration}`}
            stems={result}
            duration={result.duration}
            onBeforePlay={onBeforeStemPlayback}
            registerPause={registerStemPause}
            onError={onError}
          />
          <p>{result.saved ? '結果已保留在手機。' : '目前只是暫存；離開或重新整理後可能消失。'}</p>
          <div className="two-buttons">
            <button type="button" disabled={result.saved} onClick={() => void keepResult()}>{result.saved ? '已保留' : '保留到手機'}</button>
            <button className="danger-button" type="button" onClick={() => void removeResult()}>刪除結果</button>
          </div>
        </div>
      )}

      {fullSegments.length > 0 && resultMode === 'full' && (
        <div className="stem-results">
          <div className="stem-result-heading">
            <strong>整首分離片段</strong>
            <span>{fullSongComplete ? '全部片段已保存' : '可從下一段續做'}</span>
          </div>
          <div className="full-segment-list" role="group" aria-label="選擇四軌片段">
            {fullSegments.map((segment) => (
              <button key={segment.index} type="button" disabled={busy} className={selectedFullIndex === segment.index ? 'active' : ''} aria-pressed={selectedFullIndex === segment.index} onClick={() => void selectFullSegment(segment)}>
                第 {segment.index + 1} 段<br />{formatTime(segment.startTime, true)}–{formatTime(segment.startTime + segment.duration, true)}
              </button>
            ))}
          </div>
          {selectedFullResult ? (
            <StemMixer
              key={`full-${selectedFullIndex}`}
              stems={selectedFullResult}
              duration={selectedFullResult.duration}
              onBeforePlay={onBeforeStemPlayback}
              registerPause={registerStemPause}
              onError={onError}
              contextHolder={fullPlaybackContextRef}
              settingsHolder={fullMixerSettingsRef}
              autoPlay={autoPlayFullIndex === selectedFullIndex}
              onEnded={() => {
                const next = fullSegments.find((segment) => segment.index === (selectedFullIndex ?? -1) + 1)
                if (next) void selectFullSegment(next, true)
              }}
            />
          ) : <p>正在讀取選取片段…</p>}
          <p>想從頭連續聽，先選第 1 段再按播放。四軌共用時間軸，可調音量、Mute、Solo；播完會自動接下一段，但接縫可能短暫停頓。手動換段會停止上一段。</p>
          <button className="ai-cancel-button" type="button" disabled={busy} onClick={() => void removeFullResults()}>刪除整首分離進度與音軌</button>
        </div>
      )}

      <small className="experiment-note">整首模式會逐段儲存壓縮四軌；首次在 iPhone 實測前，請先用短歌曲驗證 M4A 播放與續做。關閉分離頁面時，正在處理的那一段需要重做。</small>
    </section>
  )
}
