export interface CachedAiModel {
  key: 'scnet-base-fp16-v1'
  size: number
  cachedAt: string
}

export interface StoredStemSet {
  key: 'current'
  sourceImportedAt: string
  sourceName: string
  startTime: number
  duration: number
  sampleRate: 44_100
  format: 'wav' | 'm4a'
  bass: Blob
  drums: Blob
  vocals: Blob
  other: Blob
  savedAt: string
}

export interface FullSongSegmentMeta {
  index: number
  sourceImportedAt: string
  startTime: number
  duration: number
  size: number
}

export interface StoredFullSongSegment extends Omit<StoredStemSet, 'key' | 'format'> {
  key: number
  format: 'm4a'
}

const databaseName = 'transcribe-mobile-ai'
const databaseVersion = 4
const modelStore = 'models'
const stemStore = 'stem-results'
const fullSongStore = 'full-song-segments'

function openDatabase(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(databaseName, databaseVersion)
    request.onupgradeneeded = (event) => {
      const database = request.result
      if (!database.objectStoreNames.contains(modelStore)) {
        database.createObjectStore(modelStore, { keyPath: 'key' })
      }
      if (!database.objectStoreNames.contains(stemStore)) {
        database.createObjectStore(stemStore, { keyPath: 'key' })
      }
      if (!database.objectStoreNames.contains(fullSongStore)) {
        database.createObjectStore(fullSongStore, { keyPath: 'key' })
      }
      if (event.oldVersion < 3 && request.transaction && database.objectStoreNames.contains(modelStore)) {
        // Remove the older phone-incompatible HTDemucs metadata. SCNet uses
        // the same metadata key across its WebGPU and low-memory WASM modes.
        request.transaction.objectStore(modelStore).clear()
      }
    }
    request.onsuccess = () => resolve(request.result)
    request.onerror = () => reject(request.error ?? new Error('無法開啟本機 AI 儲存空間。'))
  })
}

function complete(transaction: IDBTransaction): Promise<void> {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve()
    transaction.onerror = () => reject(transaction.error ?? new Error('本機 AI 資料儲存失敗。'))
    transaction.onabort = () => reject(transaction.error ?? new Error('本機 AI 資料儲存已取消。'))
  })
}

async function getValue<T>(storeName: string, key: IDBValidKey): Promise<T | null> {
  const database = await openDatabase()
  try {
    return await new Promise((resolve, reject) => {
      const request = database.transaction(storeName, 'readonly').objectStore(storeName).get(key)
      request.onsuccess = () => resolve((request.result as T | undefined) ?? null)
      request.onerror = () => reject(request.error ?? new Error('無法讀取本機 AI 資料。'))
    })
  } finally {
    database.close()
  }
}

async function putValue<T>(storeName: string, value: T): Promise<void> {
  const database = await openDatabase()
  try {
    const transaction = database.transaction(storeName, 'readwrite')
    transaction.objectStore(storeName).put(value)
    await complete(transaction)
  } finally {
    database.close()
  }
}

async function deleteValue(storeName: string, key: IDBValidKey): Promise<void> {
  const database = await openDatabase()
  try {
    const transaction = database.transaction(storeName, 'readwrite')
    transaction.objectStore(storeName).delete(key)
    await complete(transaction)
  } finally {
    database.close()
  }
}

async function clearValues(storeName: string): Promise<void> {
  const database = await openDatabase()
  try {
    const transaction = database.transaction(storeName, 'readwrite')
    transaction.objectStore(storeName).clear()
    await complete(transaction)
  } finally {
    database.close()
  }
}

export function getCachedModel(): Promise<CachedAiModel | null> {
  return getValue<CachedAiModel>(modelStore, 'scnet-base-fp16-v1')
}

export async function saveCachedModel(size: number): Promise<CachedAiModel> {
  const model: CachedAiModel = {
    key: 'scnet-base-fp16-v1',
    size,
    cachedAt: new Date().toISOString(),
  }
  await putValue(modelStore, model)
  return model
}

export function deleteCachedModel(): Promise<void> {
  return deleteValue(modelStore, 'scnet-base-fp16-v1')
}

export function getStoredStemSet(): Promise<StoredStemSet | null> {
  return getValue<StoredStemSet>(stemStore, 'current')
}

export async function saveStoredStemSet(stems: Omit<StoredStemSet, 'key' | 'savedAt'>): Promise<StoredStemSet> {
  const stored: StoredStemSet = {
    ...stems,
    key: 'current',
    savedAt: new Date().toISOString(),
  }
  await putValue(stemStore, stored)
  return stored
}

export function deleteStoredStemSet(): Promise<void> {
  return deleteValue(stemStore, 'current')
}

export async function listFullSongSegments(sourceImportedAt: string): Promise<FullSongSegmentMeta[]> {
  const database = await openDatabase()
  try {
    const metadata = await new Promise<FullSongSegmentMeta[]>((resolve, reject) => {
      const segments: FullSongSegmentMeta[] = []
      const request = database.transaction(fullSongStore, 'readonly').objectStore(fullSongStore).openCursor()
      request.onsuccess = () => {
        const cursor = request.result
        if (!cursor) {
          resolve(segments)
          return
        }
        const segment = cursor.value as StoredFullSongSegment
        if (segment.sourceImportedAt === sourceImportedAt) {
          segments.push({
            index: segment.key,
            sourceImportedAt: segment.sourceImportedAt,
            startTime: segment.startTime,
            duration: segment.duration,
            size: segment.bass.size + segment.drums.size + segment.vocals.size + segment.other.size,
          })
        }
        cursor.continue()
      }
      request.onerror = () => reject(request.error ?? new Error('無法讀取整首分離進度。'))
    })
    return metadata.sort((first, second) => first.index - second.index)
  } finally {
    database.close()
  }
}

export function getFullSongSegment(index: number): Promise<StoredFullSongSegment | null> {
  return getValue<StoredFullSongSegment>(fullSongStore, index)
}

export async function saveFullSongSegment(
  index: number,
  stems: Omit<StoredStemSet, 'key' | 'savedAt' | 'format'> & { format: 'm4a' },
): Promise<FullSongSegmentMeta> {
  const stored: StoredFullSongSegment = {
    ...stems,
    key: index,
    savedAt: new Date().toISOString(),
  }
  await putValue(fullSongStore, stored)
  return {
    index,
    sourceImportedAt: stored.sourceImportedAt,
    startTime: stored.startTime,
    duration: stored.duration,
    size: stored.bass.size + stored.drums.size + stored.vocals.size + stored.other.size,
  }
}

export function deleteFullSongSegments(): Promise<void> {
  return clearValues(fullSongStore)
}
