import {
  compactStorageScale,
  stemIds,
  type CompactSeparationResult,
  type CompactStereoStem,
  type StemId,
} from './separation'

export function createCompactSeparationAccumulator(totalSamples: number): CompactSeparationResult {
  const createStem = (): CompactStereoStem => ({
    left: new Int16Array(totalSamples),
    right: new Int16Array(totalSamples),
  })
  return { bass: createStem(), drums: createStem(), vocals: createStem(), other: createStem() }
}

/** Append a model segment at its absolute sample position. Both the current
 * eight-second result and full-length accumulator use compact 16-bit PCM. */
export function appendCompactSeparationSegment(
  target: CompactSeparationResult,
  segment: CompactSeparationResult,
  startSample: number,
  overlapSamples: number,
): void {
  for (const id of stemIds) {
    const targetStem = target[id]
    const sourceStem = segment[id]
    const copyLength = Math.min(sourceStem.left.length, targetStem.left.length - startSample)
    if (copyLength <= 0) continue
    const overlap = startSample === 0 ? 0 : Math.min(overlapSamples, copyLength)
    for (const channel of ['left', 'right'] as const) {
      const destination = targetStem[channel]
      const source = sourceStem[channel]
      for (let index = 0; index < overlap; index += 1) {
        const fadeIn = (index + 1) / (overlap + 1)
        const previous = destination[startSample + index] ?? 0
        const incoming = source[index] ?? 0
        destination[startSample + index] = Math.round(previous * (1 - fadeIn) + incoming * fadeIn)
      }
      for (let index = overlap; index < copyLength; index += 1) {
        destination[startSample + index] = source[index] ?? 0
      }
    }
  }
}

function lowPassCompactChannel(channel: Int16Array, cutoffHz: number, sampleRate = 44_100): void {
  const omega = 2 * Math.PI * cutoffHz / sampleRate
  const cosine = Math.cos(omega)
  const sine = Math.sin(omega)
  const alpha = sine / (2 * Math.SQRT1_2)
  const a0 = 1 + alpha
  const b0 = ((1 - cosine) / 2) / a0
  const b1 = (1 - cosine) / a0
  const b2 = b0
  const a1 = (-2 * cosine) / a0
  const a2 = (1 - alpha) / a0
  let x1 = 0
  let x2 = 0
  let y1 = 0
  let y2 = 0
  for (let index = 0; index < channel.length; index += 1) {
    const input = (channel[index] ?? 0) / 32_768
    const output = b0 * input + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2
    channel[index] = Math.max(-32_768, Math.min(32_767, Math.round(output * 32_768)))
    x2 = x1
    x1 = input
    y2 = y1
    y1 = output
  }
}

/** Filters after joining, so filter state cannot restart at segment boundaries.
 * Returns the gain used when encoding all four stems to final PCM16 WAV. */
export function finishCompactSeparation(result: CompactSeparationResult): number {
  const cutoffs: Record<StemId, number> = { bass: 8_000, drums: 14_000, vocals: 16_000, other: 18_000 }
  let peak = 0
  for (const id of stemIds) {
    for (const channel of [result[id].left, result[id].right]) {
      lowPassCompactChannel(channel, cutoffs[id])
      for (let index = 0; index < channel.length; index += 1) {
        peak = Math.max(peak, Math.abs(channel[index] ?? 0))
      }
    }
  }
  const originalPeak = peak / (32_768 * compactStorageScale)
  return Math.min(1, originalPeak > 0.98 ? 0.98 / originalPeak : 1) / compactStorageScale
}
