import { useCallback, useEffect, useRef, useState } from 'react'
import { AiSeparationPanel } from './components/AiSeparationPanel'
import {
  formatBytes,
  formatTime,
  playableStart,
  validateAudioFile,
  type LoopRegion,
  type SourceKind,
} from './lib/audio'
import {
  detectLocalAiCapabilities,
  type LocalAiCapabilities,
} from './lib/ai-capabilities'
import {
  createFlatEq,
  clampHighCut,
  eqBands,
  eqPresets,
  normalizeEq,
  type EqBandId,
  type EqSettings,
} from './lib/eq'
import {
  deleteAudio,
  getStorageEstimate,
  loadAudio,
  requestPersistentStorage,
  saveAudio,
  type StoredAudio,
} from './lib/storage'
import { deleteFullSongSegments, deleteStoredStemSet } from './lib/ai-storage'
import type { CapturedAudio } from './lib/capture-plan'

const speedOptions = [0.5, 0.75, 1, 1.25, 1.5] as const
const playerSettingsKey = 'transcribe-pwa-player-settings-v1'

interface PlayerSettings {
  rate: number
  volume: number
  loop: LoopRegion | null
  eq: EqSettings
}

interface LoadedAudio extends Omit<StoredAudio, 'key' | 'blob'> {
  url: string
}

interface AudioGraph {
  context: AudioContext
  mediaSource: MediaElementAudioSourceNode
  outputConnected: boolean
  filters: Record<EqBandId, BiquadFilterNode>
  highCutFilters: [BiquadFilterNode, BiquadFilterNode]
  highCutWet: GainNode
  highCutDry: GainNode
  wet: GainNode
  dry: GainNode
  output: GainNode
}

interface BeforeInstallPromptEvent extends Event {
  prompt(): Promise<void>
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed'; platform: string }>
}

function loadSettings(): PlayerSettings {
  try {
    const value = JSON.parse(localStorage.getItem(playerSettingsKey) ?? '') as Partial<PlayerSettings>
    return {
      rate: speedOptions.includes(value.rate as typeof speedOptions[number]) ? value.rate! : 1,
      volume: typeof value.volume === 'number' ? Math.min(Math.max(value.volume, 0), 1) : 1,
      loop: value.loop && Number.isFinite(value.loop.start) && Number.isFinite(value.loop.end)
        ? value.loop
        : null,
      eq: normalizeEq(value.eq),
    }
  } catch {
    return { rate: 1, volume: 1, loop: null, eq: createFlatEq() }
  }
}

function sourceLabel(kind: SourceKind): string {
  return kind === 'drive' ? '雲端硬碟／手機檔案' : '手機檔案／雲端硬碟'
}

function BrandMark() {
  return (
    <span className="brand-mark" aria-hidden="true">
      {[8, 18, 12, 22].map((height, index) => (
        <span className="brand-bar" key={index} style={{ height }} />
      ))}
    </span>
  )
}

export default function App() {
  const initialSettings = useRef(loadSettings())
  const audioRef = useRef<HTMLAudioElement>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)
  const objectUrlRef = useRef<string | null>(null)
  const sourceKindRef = useRef<SourceKind>('device')
  const animationFrameRef = useRef<number | null>(null)
  const audioGraphRef = useRef<AudioGraph | null>(null)
  const captureInProgressRef = useRef(false)
  const stemPauseRef = useRef<(() => void) | null>(null)

  const [source, setSource] = useState<LoadedAudio | null>(null)
  const [initializing, setInitializing] = useState(true)
  const [importing, setImporting] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [playing, setPlaying] = useState(false)
  const [duration, setDuration] = useState(0)
  const [currentTime, setCurrentTime] = useState(0)
  const [rate, setRate] = useState(initialSettings.current.rate)
  const [volume, setVolume] = useState(initialSettings.current.volume)
  const [loop, setLoop] = useState<LoopRegion | null>(initialSettings.current.loop)
  const [eq, setEq] = useState<EqSettings>(initialSettings.current.eq)
  const [online, setOnline] = useState(navigator.onLine)
  const [storageEstimate, setStorageEstimate] = useState<StorageEstimate | null>(null)
  const [storagePersistent, setStoragePersistent] = useState<boolean | null>(null)
  const [installPrompt, setInstallPrompt] = useState<BeforeInstallPromptEvent | null>(null)
  const [showInstallHelp, setShowInstallHelp] = useState(false)
  const [highCutText, setHighCutText] = useState(String(initialSettings.current.eq.highCut.frequency))
  const [aiCapabilities, setAiCapabilities] = useState<LocalAiCapabilities | null>(null)
  const [checkingAi, setCheckingAi] = useState(false)

  const refreshStorage = useCallback(async () => {
    setStorageEstimate(await getStorageEstimate())
    if (navigator.storage?.persisted) {
      try {
        setStoragePersistent(await navigator.storage.persisted())
      } catch {
        setStoragePersistent(null)
      }
    }
  }, [])

  const showAiError = useCallback((message: string) => {
    setError(message)
  }, [])

  const pauseForSeparation = useCallback(() => {
    audioRef.current?.pause()
    stemPauseRef.current?.()
  }, [])

  const registerStemPause = useCallback((pause: (() => void) | null) => {
    stemPauseRef.current = pause
  }, [])

  const pauseOriginalForStems = useCallback(() => {
    audioRef.current?.pause()
    // Capture mutes this element to prevent tail leakage. Unmute only on the
    // next explicit playback tap; the original output path stays disconnected.
    if (audioRef.current) audioRef.current.muted = false
  }, [])

  const applyStoredAudio = useCallback((stored: StoredAudio) => {
    if (objectUrlRef.current) URL.revokeObjectURL(objectUrlRef.current)
    const url = URL.createObjectURL(stored.blob)
    objectUrlRef.current = url
    setSource({
      name: stored.name,
      type: stored.type,
      size: stored.size,
      format: stored.format,
      sourceKind: stored.sourceKind,
      importedAt: stored.importedAt,
      url,
    })
    setDuration(0)
    setCurrentTime(0)
  }, [])

  useEffect(() => {
    let active = true
    void Promise.all([loadAudio(), getStorageEstimate()])
      .then(([stored, estimate]) => {
        if (!active) return
        if (stored) applyStoredAudio(stored)
        setStorageEstimate(estimate)
      })
      .catch((reason: unknown) => {
        if (active) setError(reason instanceof Error ? reason.message : '無法開啟本機音訊資料庫。')
      })
      .finally(() => {
        if (active) setInitializing(false)
      })

    return () => {
      active = false
      if (objectUrlRef.current) URL.revokeObjectURL(objectUrlRef.current)
      if (audioGraphRef.current) void audioGraphRef.current.context.close()
    }
  }, [applyStoredAudio])

  useEffect(() => {
    const audio = audioRef.current
    if (!audio) return
    const graph = audioGraphRef.current
    if (graph) {
      graph.output.gain.setValueAtTime(volume, graph.context.currentTime)
      audio.volume = 1
    } else {
      audio.volume = volume
    }
    audio.playbackRate = rate
    audio.preservesPitch = true
  }, [rate, source, volume])

  useEffect(() => {
    localStorage.setItem(playerSettingsKey, JSON.stringify({ rate, volume, loop, eq }))
  }, [eq, loop, rate, volume])

  useEffect(() => {
    const graph = audioGraphRef.current
    if (!graph) return
    const now = graph.context.currentTime
    for (const band of eqBands) {
      graph.filters[band.id].gain.setTargetAtTime(eq.bands[band.id], now, 0.015)
    }
    for (const filter of graph.highCutFilters) {
      filter.frequency.setTargetAtTime(eq.highCut.frequency, now, 0.015)
    }
    graph.highCutWet.gain.setTargetAtTime(eq.highCut.enabled ? 1 : 0, now, 0.01)
    graph.highCutDry.gain.setTargetAtTime(eq.highCut.enabled ? 0 : 1, now, 0.01)
    graph.wet.gain.setTargetAtTime(eq.bypassed ? 0 : 1, now, 0.01)
    graph.dry.gain.setTargetAtTime(eq.bypassed ? 1 : 0, now, 0.01)
  }, [eq])

  useEffect(() => {
    setHighCutText(String(eq.highCut.frequency))
  }, [eq.highCut.frequency])

  useEffect(() => {
    const handleOnline = () => setOnline(true)
    const handleOffline = () => setOnline(false)
    const handleInstall = (event: Event) => {
      event.preventDefault()
      setInstallPrompt(event as BeforeInstallPromptEvent)
    }
    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)
    window.addEventListener('beforeinstallprompt', handleInstall)
    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
      window.removeEventListener('beforeinstallprompt', handleInstall)
    }
  }, [])

  useEffect(() => {
    const audio = audioRef.current
    if (!audio || !playing || !loop?.enabled) return

    const checkLoop = () => {
      if (!captureInProgressRef.current && (audio.currentTime >= loop.end - 0.025 || audio.currentTime < loop.start - 0.1)) {
        audio.currentTime = loop.start
        setCurrentTime(loop.start)
      }
      animationFrameRef.current = requestAnimationFrame(checkLoop)
    }
    animationFrameRef.current = requestAnimationFrame(checkLoop)
    return () => {
      if (animationFrameRef.current !== null) cancelAnimationFrame(animationFrameRef.current)
      animationFrameRef.current = null
    }
  }, [loop, playing])

  const chooseSource = (kind: SourceKind) => {
    sourceKindRef.current = kind
    setError(null)
    if (fileInputRef.current) {
      fileInputRef.current.value = ''
      fileInputRef.current.click()
    }
  }

  const importFile = async (file: File) => {
    const validation = validateAudioFile(file)
    if (!validation.ok || !validation.format) {
      setError(validation.message ?? '不支援這個音檔。')
      return
    }

    setImporting(true)
    setError(null)
    try {
      const estimate = await getStorageEstimate()
      const available = estimate?.quota !== undefined && estimate.usage !== undefined
        ? estimate.quota - estimate.usage
        : null
      if (available !== null && file.size + 16 * 1024 * 1024 > available) {
        throw new Error('瀏覽器可用空間不足，請先刪除舊音檔或釋放手機空間。')
      }

      const importedAt = new Date().toISOString()
      await deleteStoredStemSet()
      await deleteFullSongSegments()
      const stored = await saveAudio({
        name: file.name,
        type: file.type,
        size: file.size,
        format: validation.format,
        sourceKind: sourceKindRef.current,
        importedAt,
        blob: file,
      })
      applyStoredAudio(stored)
      setLoop(null)
      setPlaying(false)
      setStoragePersistent(await requestPersistentStorage())
      await refreshStorage()
    } catch (reason) {
      const message = reason instanceof DOMException && reason.name === 'QuotaExceededError'
        ? '瀏覽器空間不足，無法保存這個音檔。'
        : reason instanceof Error ? reason.message : '音檔匯入失敗。'
      setError(message)
    } finally {
      setImporting(false)
    }
  }

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (file) void importFile(file)
  }

  const ensureAudioGraph = async (audio: HTMLAudioElement) => {
    try {
      let graph = audioGraphRef.current
      if (!graph) {
        const context = new AudioContext()
        const mediaSource = context.createMediaElementSource(audio)
        const filters = {} as Record<EqBandId, BiquadFilterNode>
        for (const [index, band] of eqBands.entries()) {
          const filter = context.createBiquadFilter()
          filter.type = index === 0 ? 'lowshelf' : index === eqBands.length - 1 ? 'highshelf' : 'peaking'
          filter.frequency.value = band.frequency
          filter.gain.value = eq.bands[band.id]
          if (filter.type === 'peaking') filter.Q.value = Math.SQRT2
          filters[band.id] = filter
        }

        const highCutFilters = [context.createBiquadFilter(), context.createBiquadFilter()] as [BiquadFilterNode, BiquadFilterNode]
        highCutFilters[0].type = 'lowpass'
        highCutFilters[0].Q.value = 0.5412
        highCutFilters[1].type = 'lowpass'
        highCutFilters[1].Q.value = 1.3065
        for (const filter of highCutFilters) filter.frequency.value = eq.highCut.frequency

        const highCutWet = context.createGain()
        const highCutDry = context.createGain()
        const wet = context.createGain()
        const dry = context.createGain()
        const output = context.createGain()

        mediaSource.connect(dry).connect(output)
        let previous: AudioNode = mediaSource
        for (const band of eqBands) {
          previous.connect(filters[band.id])
          previous = filters[band.id]
        }
        previous.connect(highCutDry).connect(wet)
        previous.connect(highCutFilters[0]).connect(highCutFilters[1]).connect(highCutWet).connect(wet)
        wet.connect(output)
        output.connect(context.destination)

        highCutWet.gain.value = eq.highCut.enabled ? 1 : 0
        highCutDry.gain.value = eq.highCut.enabled ? 0 : 1
        wet.gain.value = eq.bypassed ? 0 : 1
        dry.gain.value = eq.bypassed ? 1 : 0
        output.gain.value = volume
        graph = { context, mediaSource, outputConnected: true, filters, highCutFilters, highCutWet, highCutDry, wet, dry, output }
        audioGraphRef.current = graph
      }

      if (!graph.outputConnected) {
        graph.output.connect(graph.context.destination)
        graph.outputConnected = true
      }
      audio.volume = 1
      graph.output.gain.setValueAtTime(volume, graph.context.currentTime)
      if (graph.context.state === 'suspended') await graph.context.resume()
    } catch {
      // Desktop browsers can still use HTMLMediaElement.volume as a fallback.
      audio.volume = volume
    }
  }

  const captureForSeparation = async (
    startTime: number,
    requestedDuration: number,
    signal: AbortSignal,
  ): Promise<CapturedAudio> => {
    if (signal.aborted) throw new DOMException('音訊擷取已取消。', 'AbortError')
    const audio = audioRef.current
    if (!audio || !source) throw new Error('找不到目前歌曲，請重新載入音檔。')

    await ensureAudioGraph(audio)
    if (signal.aborted) throw new DOMException('音訊擷取已取消。', 'AbortError')
    const graph = audioGraphRef.current
    if (!graph) throw new Error('Safari 無法建立低記憶體音訊擷取器。')

    const availableDuration = Math.max(0, audio.duration - startTime)
    const captureDuration = Math.min(requestedDuration, availableDuration)
    if (!Number.isFinite(captureDuration) || captureDuration <= 0.05) {
      throw new Error('目前位置已經在歌曲結尾，請把播放位置往前移。')
    }

    const restoreTime = audio.currentTime
    audio.pause()
    const originalRate = audio.playbackRate
    audio.playbackRate = 1
    audio.preservesPitch = false
    audio.currentTime = Math.max(0, startTime)

    const processor = graph.context.createScriptProcessor(4_096, 2, 2)
    const silentOutput = graph.context.createGain()
    silentOutput.gain.value = 0
    const targetFrames = Math.ceil(captureDuration * graph.context.sampleRate)
    const left = new Int16Array(targetFrames)
    const right = new Int16Array(targetFrames)
    let capturedFrames = 0
    let recordingStarted = false
    let finishCapture: (() => void) | null = null
    let failCapture: ((reason: unknown) => void) | null = null
    let timeoutId = 0

    const captured = new Promise<void>((resolve, reject) => {
      finishCapture = resolve
      failCapture = reject
    })

    processor.onaudioprocess = (event) => {
      if (!recordingStarted || audio.seeking || capturedFrames >= targetFrames) return
      const remaining = targetFrames - capturedFrames
      const frameCount = Math.min(event.inputBuffer.length, remaining)
      const inputLeft = event.inputBuffer.getChannelData(0)
      const inputRight = event.inputBuffer.getChannelData(event.inputBuffer.numberOfChannels > 1 ? 1 : 0)
      for (let index = 0; index < frameCount; index += 1) {
        const leftSample = Math.max(-1, Math.min(1, inputLeft[index] ?? 0))
        const rightSample = Math.max(-1, Math.min(1, inputRight[index] ?? 0))
        left[capturedFrames + index] = leftSample < 0
          ? Math.round(leftSample * 32_768)
          : Math.round(leftSample * 32_767)
        right[capturedFrames + index] = rightSample < 0
          ? Math.round(rightSample * 32_768)
          : Math.round(rightSample * 32_767)
      }
      capturedFrames += frameCount
      if (capturedFrames >= targetFrames) finishCapture?.()
    }

    const handleEnded = () => {
      if (capturedFrames > 0) finishCapture?.()
      else failCapture?.(new Error('歌曲在擷取開始前就已播放完畢。'))
    }
    const handleAbort = () => {
      failCapture?.(new DOMException('音訊擷取已取消。', 'AbortError'))
    }
    const handlePlaying = () => {
      recordingStarted = true
    }

    graph.mediaSource.connect(processor)
    processor.connect(silentOutput).connect(graph.context.destination)
    if (graph.outputConnected) {
      graph.output.disconnect(graph.context.destination)
      graph.outputConnected = false
    }
    graph.output.gain.cancelScheduledValues(graph.context.currentTime)
    graph.output.gain.setValueAtTime(0, graph.context.currentTime)
    audio.muted = false
    captureInProgressRef.current = true
    audio.addEventListener('ended', handleEnded, { once: true })
    audio.addEventListener('playing', handlePlaying, { once: true })
    signal.addEventListener('abort', handleAbort, { once: true })

    try {
      timeoutId = window.setTimeout(() => {
        failCapture?.(new Error('Safari 沒有完成短片段擷取，請重新載入頁面後再試。'))
      }, Math.ceil(captureDuration * 1_000) + 5_000)
      await audio.play()
      recordingStarted = true
      await captured
    } finally {
      window.clearTimeout(timeoutId)
      // Keep the speaker path disconnected until the user explicitly plays again.
      // Reconnecting it here let Safari emit the last buffered audio quantum.
      audio.muted = true
      audio.pause()
      captureInProgressRef.current = false
      audio.removeEventListener('ended', handleEnded)
      audio.removeEventListener('playing', handlePlaying)
      signal.removeEventListener('abort', handleAbort)
      processor.onaudioprocess = null
      graph.mediaSource.disconnect(processor)
      processor.disconnect()
      silentOutput.disconnect()
      graph.output.gain.cancelScheduledValues(graph.context.currentTime)
      graph.output.gain.setValueAtTime(0, graph.context.currentTime)
      audio.playbackRate = originalRate
      audio.preservesPitch = true
      audio.currentTime = restoreTime
      setCurrentTime(restoreTime)
    }

    if (capturedFrames <= 0) throw new Error('沒有擷取到可供 AI 處理的音訊。')
    return {
      left: left.subarray(0, capturedFrames),
      right: right.subarray(0, capturedFrames),
      sampleRate: graph.context.sampleRate,
      duration: capturedFrames / graph.context.sampleRate,
    }
  }

  const handlePlayPause = async () => {
    const audio = audioRef.current
    if (!audio || !source || captureInProgressRef.current) return
    setError(null)
    if (!audio.paused) {
      audio.pause()
      return
    }

    audio.currentTime = playableStart(audio.currentTime, audio.duration, loop)
    audio.playbackRate = rate
    audio.preservesPitch = true
    try {
      stemPauseRef.current?.()
      await ensureAudioGraph(audio)
      audio.muted = false
      await audio.play()
      if ('mediaSession' in navigator) {
        navigator.mediaSession.metadata = new MediaMetadata({
          title: source.name,
          artist: 'Transcribe Mobile Practice',
        })
      }
    } catch {
      setError('無法開始播放。請確認音檔格式，並再按一次播放。')
    }
  }

  const seekTo = (value: number) => {
    const audio = audioRef.current
    const knownDuration = duration || audio?.duration || 0
    if (!audio || knownDuration <= 0) return
    const next = Math.min(Math.max(value, 0), knownDuration)
    audio.currentTime = next
    setCurrentTime(next)
  }

  const setPlaybackRate = (value: number) => {
    const audio = audioRef.current
    if (audio) {
      audio.preservesPitch = true
      audio.playbackRate = value
    }
    setRate(value)
  }

  const setPlayerVolume = (value: number) => {
    const normalized = Math.min(Math.max(value, 0), 1)
    const graph = audioGraphRef.current
    if (graph) {
      graph.output.gain.setValueAtTime(normalized, graph.context.currentTime)
    } else if (audioRef.current) {
      audioRef.current.volume = normalized
    }
    setVolume(normalized)
  }

  const updateEqBand = (id: EqBandId, value: number) => {
    setEq((current) => ({ ...current, bands: { ...current.bands, [id]: value } }))
  }

  const applyPreset = (preset: typeof eqPresets[number]) => {
    setEq((current) => ({
      bands: { ...preset.bands },
      bypassed: false,
      highCut: preset.highCut ? { ...preset.highCut } : { ...current.highCut, enabled: false },
    }))
  }

  const commitHighCut = () => {
    const frequency = clampHighCut(Number(highCutText))
    setHighCutText(String(frequency))
    setEq((current) => ({ ...current, highCut: { ...current.highCut, frequency } }))
  }

  const checkLocalAi = async () => {
    setCheckingAi(true)
    try {
      setAiCapabilities(await detectLocalAiCapabilities())
    } finally {
      setCheckingAi(false)
    }
  }

  const setLoopStart = () => {
    if (!source || duration <= 0) return
    const start = Math.min(currentTime, Math.max(duration - 0.05, 0))
    const end = loop?.end && loop.end > start ? loop.end : duration
    setLoop({ start, end, enabled: loop?.enabled ?? false })
  }

  const setLoopEnd = () => {
    if (!source || duration <= 0) return
    const start = loop?.start ?? 0
    if (currentTime <= start + 0.05) {
      setError('循環終點必須晚於起點。')
      return
    }
    setError(null)
    setLoop({ start, end: currentTime, enabled: true })
  }

  const toggleLoop = () => {
    if (!loop) {
      setError('請先在播放位置設定 A 與 B。')
      return
    }
    setLoop({ ...loop, enabled: !loop.enabled })
  }

  const removeSource = async () => {
    if (!source || !window.confirm(`要從這支手機刪除「${source.name}」嗎？原始檔不會被刪除。`)) return
    const audio = audioRef.current
    audio?.pause()
    if (audio) audio.removeAttribute('src')
    await deleteAudio()
    await deleteStoredStemSet()
    await deleteFullSongSegments()
    if (objectUrlRef.current) URL.revokeObjectURL(objectUrlRef.current)
    objectUrlRef.current = null
    setSource(null)
    setPlaying(false)
    setDuration(0)
    setCurrentTime(0)
    setLoop(null)
    await refreshStorage()
  }

  const installApp = async () => {
    if (!installPrompt) {
      setShowInstallHelp(true)
      return
    }
    await installPrompt.prompt()
    await installPrompt.userChoice
    setInstallPrompt(null)
  }

  const usageText = storageEstimate?.usage !== undefined && storageEstimate.quota !== undefined
    ? `${formatBytes(storageEstimate.usage)} / ${formatBytes(storageEstimate.quota)}`
    : '由 iPhone 管理'

  return (
    <div className="app-shell">
      <header className="app-header">
        <div className="brand">
          <BrandMark />
          <span><strong>TRANSCRIBE</strong><small>MOBILE PRACTICE PWA</small></span>
        </div>
        <span className={`status-badge ${online ? '' : 'offline'}`}>
          <i />{online ? 'ONLINE' : 'OFFLINE'}
        </span>
      </header>

      <main>
        {error && (
          <div className="error-banner" role="alert">
            <span>{error}</span>
            <button type="button" onClick={() => setError(null)}>關閉</button>
          </div>
        )}

        {initializing ? (
          <section className="center-state"><span className="spinner" /><p>正在開啟本機音訊資料庫…</p></section>
        ) : !source ? (
          <section className="welcome">
            <p className="eyebrow">IPHONE · ANDROID · LOCAL AUDIO</p>
            <h1>把想練的歌，<br />帶在身上。</h1>
            <p className="lead">音檔只會保存於這支手機的瀏覽器空間，不會上傳到網站伺服器。</p>
            <div className="source-grid">
              <button className="source-card" type="button" disabled={importing} onClick={() => chooseSource('device')}>
                <span className="source-icon">▣</span>
                <span><strong>選擇音樂檔案</strong><small>可從 iPhone、iCloud Drive 或 Google Drive 選擇 MP3、WAV、FLAC</small></span>
                <b>›</b>
              </button>
            </div>
            {importing && <div className="importing"><span className="spinner" />正在複製到手機本機空間…</div>}
            <button className="install-button" type="button" onClick={() => void installApp()}>加入手機主畫面</button>
            <p className="privacy-note">第一次開啟需要網路；安裝並匯入後可以離線練習。</p>
          </section>
        ) : (
          <section className="workspace">
            <div className="track-heading">
              <div>
                <p className="eyebrow">NOW PRACTICING</p>
                <h1>{source.name}</h1>
                <p className="track-meta">{source.format.toUpperCase()} · {formatBytes(source.size)} · {sourceLabel(source.sourceKind)}</p>
              </div>
              <button className="outline-button" type="button" onClick={() => chooseSource('device')}>更換音源</button>
            </div>

            <section className="panel timeline-panel">
              <div className="panel-heading"><span>播放時間軸</span><b>{duration > 0 ? 'READY' : 'LOADING'}</b></div>
              <input
                aria-label="播放位置"
                type="range"
                min="0"
                max={duration || 0}
                step="0.01"
                value={Math.min(currentTime, duration || 0)}
                disabled={duration <= 0}
                onChange={(event) => seekTo(Number(event.target.value))}
              />
              <div className="time-readout"><strong>{formatTime(currentTime, true)}</strong><span>/ {formatTime(duration, true)}</span></div>
            </section>

            <div className="transport">
              <button type="button" onClick={() => seekTo(currentTime - 10)}>−10</button>
              <button className="play-button" type="button" aria-label={playing ? '暫停' : '播放'} onClick={() => void handlePlayPause()}>{playing ? 'Ⅱ' : '▶'}</button>
              <button type="button" onClick={() => seekTo(currentTime + 10)}>+10</button>
            </div>

            <section className="panel">
              <div className="panel-heading"><span>播放速度</span><b>{rate.toFixed(2)}× · 保持音高</b></div>
              <div className="speed-grid">
                {speedOptions.map((speed) => (
                  <button className={speed === rate ? 'active' : ''} type="button" key={speed} onClick={() => setPlaybackRate(speed)}>{speed}×</button>
                ))}
              </div>
            </section>

            <AiSeparationPanel
              capabilities={aiCapabilities}
              checkingCapabilities={checkingAi}
              currentTime={currentTime}
              sourceDuration={duration}
              sourceImportedAt={source.importedAt}
              sourceName={source.name}
              onCheckCapabilities={checkLocalAi}
              onBeforeSeparation={pauseForSeparation}
              onBeforeStemPlayback={pauseOriginalForStems}
              registerStemPause={registerStemPause}
              captureClip={captureForSeparation}
              onError={showAiError}
              onStorageChanged={refreshStorage}
            />

            <section className="panel">
              <div className="panel-heading"><span>音量</span><b>{Math.round(volume * 100)}%</b></div>
              <input aria-label="音量" type="range" min="0" max="1" step="0.01" value={volume} onChange={(event) => setPlayerVolume(Number(event.target.value))} />
            </section>

            <section className="panel eq-panel">
              <div className="panel-heading">
                <span>練習 EQ</span>
                <div className="eq-actions">
                  <button type="button" onClick={() => setEq(createFlatEq())}>Reset</button>
                  <button className={eq.bypassed ? 'active' : ''} type="button" onClick={() => setEq((current) => ({ ...current, bypassed: !current.bypassed }))}>Bypass</button>
                </div>
              </div>
              <div className="preset-grid">
                {eqPresets.map((preset) => (
                  <button type="button" key={preset.name} title={preset.description} onClick={() => applyPreset(preset)}>
                    <strong>{preset.name}</strong><small>{preset.description}</small>
                  </button>
                ))}
              </div>
              <details className="eq-advanced">
                <summary>進階頻段調整</summary>
                <div className="high-cut-row">
                  <label className="check-label">
                    <input type="checkbox" checked={eq.highCut.enabled} onChange={(event) => setEq((current) => ({ ...current, highCut: { ...current.highCut, enabled: event.target.checked } }))} />
                    High Cut
                  </label>
                  <label className="frequency-input">
                    <input
                      aria-label="High Cut 截止頻率"
                      type="text"
                      inputMode="numeric"
                      value={highCutText}
                      onChange={(event) => setHighCutText(event.target.value)}
                      onBlur={commitHighCut}
                      onKeyDown={(event) => {
                        if (event.key === 'Enter') {
                          commitHighCut()
                          event.currentTarget.blur()
                        }
                      }}
                    />
                    <span>Hz</span>
                  </label>
                </div>
                <small className="eq-note">High Cut 會逐漸減少指定頻率以上的聲音。</small>
                <div className="eq-band-list">
                  {eqBands.map((band) => (
                    <label className="eq-row" key={band.id}>
                      <span>{band.label} Hz</span>
                      <input aria-label={`${band.label} Hz`} type="range" min="-12" max="12" step="0.5" value={eq.bands[band.id]} onChange={(event) => updateEqBand(band.id, Number(event.target.value))} />
                      <output>{eq.bands[band.id] > 0 ? '+' : ''}{eq.bands[band.id].toFixed(1)} dB</output>
                    </label>
                  ))}
                </div>
              </details>
            </section>

            <section className="panel">
              <div className="panel-heading">
                <span>A–B LOOP</span>
                <button className={`loop-toggle ${loop?.enabled ? 'active' : ''}`} type="button" onClick={toggleLoop}>{loop?.enabled ? '循環中' : '已關閉'}</button>
              </div>
              <div className="loop-readout">
                <span><small>A 起點</small><strong>{formatTime(loop?.start ?? 0, true)}</strong></span>
                <i>→</i>
                <span><small>B 終點</small><strong>{loop ? formatTime(loop.end, true) : '--:--.---'}</strong></span>
              </div>
              <div className="two-buttons">
                <button type="button" onClick={setLoopStart}>目前位置設為 A</button>
                <button type="button" onClick={setLoopEnd}>目前位置設為 B</button>
              </div>
              {loop && <button className="text-button" type="button" onClick={() => setLoop(null)}>清除循環區段</button>}
            </section>

            <section className="panel storage-panel">
              <div><span>這支手機的網站儲存空間</span><strong>{usageText}</strong><small>{storagePersistent ? '已取得持久化儲存' : '不是 GitHub 空間；iPhone 空間不足時仍可能清除資料'}</small></div>
              <button className="danger-button" type="button" onClick={() => void removeSource()}>刪除本機音檔</button>
            </section>
            <button className="install-button compact" type="button" onClick={() => void installApp()}>加入手機主畫面</button>
          </section>
        )}
      </main>

      <footer><span>AUDIO STAYS ON THIS DEVICE</span><span>PWA v0.5.19</span></footer>

      <input
        ref={fileInputRef}
        className="visually-hidden"
        type="file"
        accept=".mp3,.wav,.flac,audio/mpeg,audio/wav,audio/x-wav,audio/flac,audio/x-flac"
        onChange={handleFileChange}
      />
      <audio
        ref={audioRef}
        src={source?.url}
        preload="metadata"
        onLoadedMetadata={(event) => {
          setDuration(event.currentTarget.duration || 0)
          event.currentTarget.volume = audioGraphRef.current ? 1 : volume
          event.currentTarget.playbackRate = rate
          event.currentTarget.preservesPitch = true
        }}
        onTimeUpdate={(event) => setCurrentTime(event.currentTarget.currentTime)}
        onPlay={() => setPlaying(true)}
        onPause={() => setPlaying(false)}
        onEnded={() => setPlaying(false)}
        onError={() => source && setError('Safari 無法解碼這個音檔，請確認檔案未損壞。')}
      />

      {showInstallHelp && (
        <div className="modal-backdrop" role="presentation" onClick={() => setShowInstallHelp(false)}>
          <section className="install-sheet" role="dialog" aria-modal="true" aria-labelledby="install-title" onClick={(event) => event.stopPropagation()}>
            <div className="sheet-handle" />
            <p className="eyebrow">INSTALL ON IPHONE</p>
            <h2 id="install-title">加入手機主畫面</h2>
            <ol>
              <li>用 Safari 開啟這個網站。</li>
              <li>按 Safari 下方的「分享」按鈕。</li>
              <li>選擇「加入主畫面」。</li>
              <li>保持「以 Web App 打開」並按「加入」。</li>
            </ol>
            <button className="install-button" type="button" onClick={() => setShowInstallHelp(false)}>我知道了</button>
          </section>
        </div>
      )}
    </div>
  )
}
