function writeAscii(view: DataView, offset: number, value: string): void {
  for (let index = 0; index < value.length; index += 1) {
    view.setUint8(offset + index, value.charCodeAt(index))
  }
}

function floatToPcm16(value: number): number {
  const sample = Math.min(1, Math.max(-1, value))
  return sample < 0 ? Math.round(sample * 0x8000) : Math.round(sample * 0x7fff)
}

export function encodeStereoWav(
  left: Float32Array,
  right: Float32Array,
  sampleRate = 44_100,
): Blob {
  const frameCount = Math.min(left.length, right.length)
  const channelCount = 2
  const bytesPerSample = 2
  const dataSize = frameCount * channelCount * bytesPerSample
  const buffer = new ArrayBuffer(44 + dataSize)
  const view = new DataView(buffer)

  writeAscii(view, 0, 'RIFF')
  view.setUint32(4, 36 + dataSize, true)
  writeAscii(view, 8, 'WAVE')
  writeAscii(view, 12, 'fmt ')
  view.setUint32(16, 16, true)
  view.setUint16(20, 1, true)
  view.setUint16(22, channelCount, true)
  view.setUint32(24, sampleRate, true)
  view.setUint32(28, sampleRate * channelCount * bytesPerSample, true)
  view.setUint16(32, channelCount * bytesPerSample, true)
  view.setUint16(34, bytesPerSample * 8, true)
  writeAscii(view, 36, 'data')
  view.setUint32(40, dataSize, true)

  let offset = 44
  for (let index = 0; index < frameCount; index += 1) {
    view.setInt16(offset, floatToPcm16(left[index] ?? 0), true)
    view.setInt16(offset + 2, floatToPcm16(right[index] ?? 0), true)
    offset += 4
  }

  return new Blob([buffer], { type: 'audio/wav' })
}

/** Encodes an already quantized, planar stereo recording without expanding it
 * back into two full-length Float32Array buffers on memory-limited phones. */
export function encodeStereoPcm16Wav(
  left: Int16Array,
  right: Int16Array,
  gain = 1,
  sampleRate = 44_100,
): Blob {
  const frameCount = Math.min(left.length, right.length)
  const dataSize = frameCount * 4
  const buffer = new ArrayBuffer(44 + dataSize)
  const view = new DataView(buffer)
  writeAscii(view, 0, 'RIFF')
  view.setUint32(4, 36 + dataSize, true)
  writeAscii(view, 8, 'WAVE')
  writeAscii(view, 12, 'fmt ')
  view.setUint32(16, 16, true)
  view.setUint16(20, 1, true)
  view.setUint16(22, 2, true)
  view.setUint32(24, sampleRate, true)
  view.setUint32(28, sampleRate * 4, true)
  view.setUint16(32, 4, true)
  view.setUint16(34, 16, true)
  writeAscii(view, 36, 'data')
  view.setUint32(40, dataSize, true)

  const safeGain = Number.isFinite(gain) && gain >= 0 ? gain : 1
  for (let index = 0; index < frameCount; index += 1) {
    const offset = 44 + index * 4
    view.setInt16(offset, Math.max(-32_768, Math.min(32_767, Math.round((left[index] ?? 0) * safeGain))), true)
    view.setInt16(offset + 2, Math.max(-32_768, Math.min(32_767, Math.round((right[index] ?? 0) * safeGain))), true)
  }
  return new Blob([buffer], { type: 'audio/wav' })
}
