import type { FullSongSegmentMeta } from './ai-storage'

export interface FullSongWindow {
  index: number
  startTime: number
  duration: number
}

/** Each committed window is a durable checkpoint. The next window begins at
 * the exact end of the last stored window, including any short final capture. */
export function nextFullSongWindow(
  completed: FullSongSegmentMeta[],
  sourceDuration: number,
  windowSeconds = 30,
): FullSongWindow | null {
  if (!Number.isFinite(sourceDuration) || sourceDuration <= 0) return null
  if (!Number.isFinite(windowSeconds) || windowSeconds <= 0) throw new Error('分段長度必須大於零。')
  const ordered = [...completed].sort((first, second) => first.index - second.index)
  for (let index = 0; index < ordered.length; index += 1) {
    const segment = ordered[index]
    const previous = ordered[index - 1]
    const expectedStart = previous ? previous.startTime + previous.duration : 0
    if (
      segment?.index !== index ||
      !Number.isFinite(segment.startTime) ||
      !Number.isFinite(segment.duration) ||
      segment.duration <= 0 ||
      Math.abs(segment.startTime - expectedStart) > 0.05
    ) throw new Error('整首分離進度不連續，請清除進度後重試。')
  }
  const last = ordered.at(-1)
  const startTime = last ? last.startTime + last.duration : 0
  if (startTime >= sourceDuration - 0.05) return null
  return {
    index: ordered.length,
    startTime,
    duration: Math.min(windowSeconds, sourceDuration - startTime),
  }
}
